</head>
<body>
    <div class="container">
        <h1>Expense Tracker</h1>

        <div class="form-section">
            <h2 style="font-size: 16px; margin-bottom: 15px; color: #333;">Add Expense</h2>
            <div id="form-error"></div>
            <form id="expense-form">
                <div class="form-group">
                    <div>
                        <label for="amount">Amount ($)</label>
                        <input type="number" id="amount" step="0.01" min="0" placeholder="0.00">
                    </div>
                    <div>
                        <label for="category">Category</label>
                        <select id="category">
                            <option value="">Select a category</option>
                            <option value="groceries">Groceries</option>
                            <option value="transport">Transport</option>
                            <option value="bills">Bills</option>
                            <option value="fun">Fun</option>
                        </select>
                    </div>
                    <div>
                        <label for="date">Date</label>
                        <input type="date" id="date">
                    </div>
                </div>
                <div class="form-group">
                    <div style="grid-column: span 2;">
                        <label for="note">Note (optional)</label>
                        <input type="text" id="note" placeholder="Add a note...">
                    </div>
                </div>
                <button type="submit" id="add-expense">Add Expense</button>
            </form>
        </div>

        <div class="filters-section">
            <h2>Filters</h2>
            <div class="filter-group">
                <div>
                    <label for="filter-category">Category</label>
                    <select id="filter-category">
                        <option value="all">All Categories</option>
                        <option value="groceries">Groceries</option>
                        <option value="transport">Transport</option>
                        <option value="bills">Bills</option>
                        <option value="fun">Fun</option>
                    </select>
                </div>
                <div>
                    <label for="filter-from">From Date</label>
                    <input type="date" id="filter-from">
                </div>
                <div>
                    <label for="filter-to">To Date</label>
                    <input type="date" id="filter-to">
                </div>
            </div>
        </div>

        <div class="summary-section">
            <div class="summary-header">
                <h2>Total Expenses</h2>
                <div id="total">0.00</div>
            </div>
            <div>
                <p style="font-size: 12px; color: #666; margin-bottom: 10px;">By Category:</p>
                <div class="category-totals">
                    <div class="cat-total" data-cat="groceries"><strong>Groceries:</strong> $0.00</div>
                    <div class="cat-total" data-cat="transport"><strong>Transport:</strong> $0.00</div>
                    <div class="cat-total" data-cat="bills"><strong>Bills:</strong> $0.00</div>
                    <div class="cat-total" data-cat="fun"><strong>Fun:</strong> $0.00</div>
                </div>
            </div>
        </div>

        <div class="expenses-section">
            <h2>Expenses</h2>
            <div id="expenses-list"></div>
        </div>
    </div>

    <script>
        const STORAGE_KEY = 'expenses';
        const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

        document.getElementById('date').valueAsDate = new Date();

        function loadExpenses() {
            const stored = localStorage.getItem(STORAGE_KEY);
            return stored ? JSON.parse(stored) : [];
        }

        function saveExpenses(expenses) {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
        }

        function getExpenses() {
            return loadExpenses();
        }

        function addExpense(amount, category, date, note) {
            const expenses = getExpenses();
            expenses.push({
                id: Date.now(),
                amount: parseFloat(amount),
                category,
                date,
                note,
                timestamp: Date.now()
            });
            saveExpenses(expenses);
        }

        function deleteExpense(id) {
            let expenses = getExpenses();
            expenses = expenses.filter(e => e.id !== id);
            saveExpenses(expenses);
        }

        function validateForm() {
            const amount = document.getElementById('amount').value.trim();
            const category = document.getElementById('category').value;
            const date = document.getElementById('date').value;
            const errorEl = document.getElementById('form-error');

            if (!amount || isNaN(amount)) {
                errorEl.textContent = 'Please enter a valid amount';
                errorEl.classList.add('show');
                return false;
            }

            const numAmount = parseFloat(amount);
            if (numAmount <= 0) {
                errorEl.textContent = 'Amount must be greater than zero';
                errorEl.classList.add('show');
                return false;
            }

            if (!category) {
                errorEl.textContent = 'Please select a category';
                errorEl.classList.add('show');
                return false;
            }

            if (!date) {
                errorEl.textContent = 'Please select a date';
                errorEl.classList.add('show');
                return false;
            }

            errorEl.textContent = '';
            errorEl.classList.remove('show');
            return true;
        }

        function getFilteredExpenses() {
            const expenses = getExpenses();
            const categoryFilter = document.getElementById('filter-category').value;
            const fromFilter = document.getElementById('filter-from').value;
            const toFilter = document.getElementById('filter-to').value;

            return expenses.filter(exp => {
                if (categoryFilter !== 'all' && exp.category !== categoryFilter) {
                    return false;
                }
                if (fromFilter && exp.date < fromFilter) {
                    return false;
                }
                if (toFilter && exp.date > toFilter) {
                    return false;
                }
                return true;
            });
        }

        function renderExpenses() {
            const filtered = getFilteredExpenses();
            const list = document.getElementById('expenses-list');

            if (filtered.length === 0) {
                list.innerHTML = '<div class="empty-state">No expenses found</div>';
                updateSummary();
                return;
            }

            filtered.sort((a, b) => new Date(b.date) - new Date(a.date));

            list.innerHTML = filtered.map(exp => `
                <div class="expense">
                    <div class="expense-info">
                        <div class="expense-amount">$${exp.amount.toFixed(2)}</div>
                        <div class="expense-note">${exp.note ? exp.note : ''}</div>
                    </div>
                    <div class="expense-category">${exp.category}</div>
                    <div class="expense-date">${new Date(exp.date).toLocaleDateString()}</div>
                    <button class="exp-del" data-id="${exp.id}">Delete</button>
                </div>
            `).join('');

            document.querySelectorAll('.exp-del').forEach(btn => {
                btn.addEventListener('click', () => {
                    const id = parseInt(btn.dataset.id);
                    deleteExpense(id);
                    renderExpenses();
                });
            });

            updateSummary();
        }

        function updateSummary() {
            const filtered = getFilteredExpenses();
            const total = filtered.reduce((sum, exp) => sum + exp.amount, 0);

            document.getElementById('total').textContent = total.toFixed(2);

            CATEGORIES.forEach(cat => {
                const catTotal = filtered
                    .filter(exp => exp.category === cat)
                    .reduce((sum, exp) => sum + exp.amount, 0);
                const catEl = document.querySelector(`[data-cat="${cat}"]`);
                if (catEl) {
                    catEl.innerHTML = `<strong>${cat.charAt(0).toUpperCase() + cat.slice(1)}:</strong> $${catTotal.toFixed(2)}`;
                }
            });
        }

        document.getElementById('expense-form').addEventListener('submit', (e) => {
            e.preventDefault();

            if (!validateForm()) {
                return;
            }

            const amount = document.getElementById('amount').value;
            const category = document.getElementById('category').value;
            const date = document.getElementById('date').value;
            const note = document.getElementById('note').value;

            addExpense(amount, category, date, note);

            document.getElementById('amount').value = '';
            document.getElementById('category').value = '';
            document.getElementById('note').value = '';
            document.getElementById('date').valueAsDate = new Date();

            renderExpenses();
        });

        document.getElementById('filter-category').addEventListener('change', renderExpenses);
        document.getElementById('filter-from').addEventListener('change', renderExpenses);
        document.getElementById('filter-to').addEventListener('change', renderExpenses);

        renderExpenses();
    </script>
</body>
</html>
